    return [0, 0];
  }

  const fibMatrix = [[1, 1], [1, 0]];
  const result = matrixExponentiation(fibMatrix, n - 1);
  const fibSum = result[0][0] - 1; // Subtract 1 to exclude the first term (1)
  const primeCount = countPrimes(result[0][0]);

