function matrixExponentiation(matrix, n) {
  if (n === 0) {
    return [[1, 0], [0, 1]];
  } else if (n % 2 === 0) {
    const half = matrixExponentiation(matrix, n / 2);
    return multiplyMatrices(half, half);
  } else {
    const half = matrixExponentiation(matrix, (n - 1) / 2);
    return multiplyMatrices(multiplyMatrices(half, half), matrix);
  }
