def is_palindrome(s):
    # Base case: if the string is empty or has only one character, it is a palindrome
    if len(s) <= 1:
        return True

    # Check if the first and last characters are alphanumeric
    if not s[0].isalnum():
        return is_palindrome(s[1:])
    if not s[-1].isalnum():
