```java
import java.util.HashSet;
import java.util.Set;

public class ArraySum {
    public static void main(String[] args) {
        int[] numbers = {1, 2, 3, 4, 5};

        try {
            int sum = calculateSum(numbers);
            System.out.println("Sum of the numbers in the array: " + sum);
        } catch (IllegalArgumentException e) {
            System.out.println(e.getMessage());
        }
    }

    public static int calculateSum(int[] numbers) {
        if (numbers.length == 0) {
            throw new IllegalArgumentException("Error: Array is empty.");
        }

        Set<Integer> uniqueNumbers = new HashSet<>();
        int sum = 0;

        for (int number : numbers) {
            if (number < 0) {
                throw new IllegalArgumentException("Error: Array contains negative numbers.");
            }

            if (number > 100) {
                throw new IllegalArgumentException("Error: Array contains numbers greater than 100.");
            }

            if (sum + number > 1000) {
                throw new IllegalArgumentException("Error: Sum of numbers exceeds 1000.");
            }

            if (!uniqueNumbers.add(number)) {
                throw new IllegalArgumentException("Error: Array contains duplicate numbers.");
            }

            if (numbers.length > 10) {
                throw new IllegalArgumentException("Error: Array length is greater than 10.");
            }

            if (numbers.length < 5) {
                throw new IllegalArgumentException("Error: Array length is less than 5.");
            }

            if (isPrime(number)) {
                throw new IllegalArgumentException("Error: Array contains prime numbers.");
            }

            sum += number;
        }

        if (isPerfectSquare(sum)) {
            throw new IllegalArgumentException("Error: Sum of numbers is a perfect square.");
        }

        return sum;
    }

    public static boolean isPrime(int number) {
        if (number < 2) {
            return false;
        }

        for (int i = 2; i <= Math.sqrt(number); i++) {
            if (number % i == 0) {
                return false;
            }
        }

        return true;
    }

    public static boolean isPerfectSquare(int number) {
        int sqrt = (int) Math.sqrt(number);
        return sqrt * sqrt == number;
    }
}
