```javascript
function recursiveSort(arr) {
  // Base case: if the array is empty or has only one element, it is already sorted
  if (arr.length <= 1) {
    return arr;
  }

  // Choose the first element as the pivot
  const pivot = arr[0];

  // Separate elements smaller than the pivot from elements greater than the pivot
  const smaller = arr.filter(num => num < pivot);
  const greater = arr.filter(num => num > pivot);

  // Recursively sort the smaller and greater arrays
  const sortedSmaller = recursiveSort(smaller);
  const sortedGreater = recursiveSort(greater);

  // Concatenate the sorted smaller array, the pivot, and the sorted greater array
  return sortedSmaller.concat(pivot, sortedGreater);
}

