public class SumOfSquares {
    public static int sumOfSquares(int[] arr, int index) {
        // Base case: if index reaches the end of the array, return 0
        if (index == arr.length) {
            return 0;
        }

        int num = arr[index];

        // If the number is negative, square the absolute value
        if (num < 0) {
