    try:
        num = int(input("Enter a positive integer: "))
        if num <= 0:
            print("Invalid input. Please enter a positive integer.")
            return get_positive_integer()
        else:
            return num
    except ValueError:
        print("Invalid input. Please enter a positive integer.")
        return get_positive_integer()


def calculate_sum(n):
    if n == 1:
        return 1
    else:
        return n + calculate_sum(n-1)


def main():
