Here's a recursive JavaScript function to check whether a string is a palindrome, ignoring non-alphanumeric characters and case-insensitive.

```javascript
function isPalindrome(str) {
  // Remove non-alphanumeric characters and convert to lowercase
  let cleanStr = str.replace(/[^a-z0-9]/gi, "").toLowerCase();

  // Base case: if string length is 0 or 1, it's a palindrome
  if (cleanStr.length <= 1) {
    return true;
  }

  // Check if first and last characters are equal
  if (cleanStr[0] !== cleanStr[cleanStr.length - 1]) {
    return false;
  }

  // Recursively check if the substring without the first and last characters is a palindrome
  return isPalindrome(cleanStr.slice(1, cleanStr.length - 1));
}

