def longest_common_substring(string1, string2):
    memo = {} # memoization dictionary to store already computed values

    def helper(s1, s2, i, j):
        if i == 0 or j == 0: # base case: if either string is empty, no common substring exists
            return 0

        # check if the current characters match
        if s1[i-1] == s2[j-1]:
            if (i-1, j-1) in memo:
                return memo[(i-1, j-1)] + 1
            else:
                memo[(i-1, j-1)] = helper(s1, s2, i-1, j-1) + 1
                return memo[(i-1, j-1)]

        # if the current characters don't match, recursively find the longest common substring
        else:
            if (i-1, j) in memo:
                left = memo[(i-1, j)]
            else:
                memo[(i-1, j)] = helper(s1, s2, i-1, j)
                left = memo[(i-1, j)]

            if (i, j-1) in memo:
                right = memo[(i, j-1)]
            else:
                memo[(i, j-1)] = helper(s1, s2, i, j-1)
                right = memo[(i, j-1)]

            return max(left, right)

    return helper(string1, string2, len(string1), len(string2))

