int factorial(int n) {
    if (n < 0) {
        throw std::invalid_argument("Factorial not defined for negative numbers.");
    }

    if (n <= 1) {
        return 1;
    }

    if (factorialCache.find(n) != factorialCache.end()) {
        return factorialCache[n];
    }

