```javascript
function fibonacciSum(n) {
  if (n <= 0) {
    return [0, 0];
  }

  const fibMatrix = [[1, 1], [1, 0]];
  const result = matrixExponentiation(fibMatrix, n - 1);
  const fibSum = result[0][0] - 1; // Subtract 1 to exclude the first term (1)
  const primeCount = countPrimes(result[0][0]);

  return [fibSum, primeCount];
}

function matrixExponentiation(matrix, n) {
  if (n === 0) {
    return [[1, 0], [0, 1]];
  } else if (n % 2 === 0) {
    const half = matrixExponentiation(matrix, n / 2);
    return multiplyMatrices(half, half);
  } else {
    const half = matrixExponentiation(matrix, (n - 1) / 2);
    return multiplyMatrices(multiplyMatrices(half, half), matrix);
  }
}

function multiplyMatrices(a, b) {
  const result = [[0, 0], [0, 0]];

  for (let i = 0; i < 2; i++) {
    for (let j = 0; j < 2; j++) {
      for (let k = 0; k < 2; k++) {
        result[i][j] += a[i][k] * b[k][j];
      }
    }
  }

  return result;
}

function countPrimes(n) {
  let count = 0;

  for (let i = 2; i <= Math.sqrt(n); i++) {
    if (isPrime(i)) {
      count++;
    }
  }

  return count;
}

function isPrime(n) {
  if (n < 2) {
    return false;
  }

  for (let i = 2; i <= Math.sqrt(n); i++) {
    if (n % i === 0) {
      return false;
    }
  }

  return true;
}
```

