        String input = "Hello, World!";
        String reversed = reverseString(input);
        System.out.println(reversed);
    }

    public static String reverseString(String input) {
        // Base case: if the input string is empty or has only one character, return it as is
        if (input.isEmpty() || input.length() == 1) {
            return input.toLowerCase();
        }

        // Recursive case:
        // Remove the first and last characters from the input string
        String substring = input.substring(1, input.length() - 1);
        substring = substring.replaceAll("[^a-zA-Z]", ""); // Remove punctuation marks

