function mergeSortedArrays(arr1, arr2) {
  // Base cases: if one array is empty, return the other array
  if (arr1.length === 0) {
    return arr2;
  }
  if (arr2.length === 0) {
    return arr1;
  }

  // Recursive cases: compare the first elements of the two arrays
  if (arr1[0] <= arr2[0]) {
    // If arr1[0] is smaller or equal, append arr1[0] to the result and recursively merge the remaining arrays
