import java.util.Scanner;

public class FibonacciSeries {

    private static int[] memoization;

    public static void main(String[] args) {
        Scanner input = new Scanner(System.in);

        System.out.print("Enter the value of N: ");
        int n = input.nextInt();

        if (n <= 0) {
            System.out.println("Invalid input. Please enter a positive number.");
            return;
        }

        if (n > 1000) {
            System.out.println("Invalid input. Please enter a number within the limit of 1000.");
            return;
        }

        memoization = new int[n];

        System.out.println("Fibonacci series up to " + n + " numbers:");
        for (int i = 0; i < n; i++) {
            int fibonacciNumber = calculateFibonacci(i);
            System.out.println(i + ": " + fibonacciNumber);
        }

        int sum = calculateSum(n);
        System.out.println("Sum of all Fibonacci numbers: " + sum);

        double average = calculateAverage(n);
        System.out.println("Average of Fibonacci numbers: " + average);

        int product = calculateProduct(n);
        System.out.println("Product of all Fibonacci numbers: " + product);

        int numberToCheck = 8;
        boolean isFibonacci = isFibonacciNumber(numberToCheck);
        System.out.println("Is " + numberToCheck + " a Fibonacci number? " + isFibonacci);

        int nthFibonacci = calculateNthFibonacci(10);
        System.out.println("The 10th Fibonacci number: " + nthFibonacci);
    }

    private static int calculateFibonacci(int n) {
        if (n == 0) {
            return 0;
        }

        if (n == 1) {
            return 1;
        }

        if (memoization[n] != 0) {
            return memoization[n];
        }

        int fibonacciNumber = calculateFibonacci(n - 1) + calculateFibonacci(n - 2);
        memoization[n] = fibonacciNumber;
        return fibonacciNumber;
    }

    private static int calculateSum(int n) {
        int sum = 0;
        for (int i = 0; i < n; i++) {
            sum += calculateFibonacci(i);
        }
        return sum;
    }

    private static double calculateAverage(int n) {
        int sum = calculateSum(n);
        return (double) sum / n;
    }

    private static int calculateProduct(int n) {
        int product = 1;
        for (int i = 0; i < n; i++) {
            product *= calculateFibonacci(i);
        }
        return product;
    }

    private static boolean isFibonacciNumber(int number) {
        int i = 0;
        int fibonacciNumber = 0;
        while (fibonacciNumber < number) {
            fibonacciNumber = calculateFibonacci(i);
            i++;
        }
        return fibonacciNumber == number;
    }

    private static int calculateNthFibonacci(int n) {
        int current = 0;
        int next = 1;

        for (int i = 2; i <= n; i++) {
            int temp = current + next;
            current = next;
            next = temp;
        }

        return current;
    }
}

