#include <iostream>
#include <vector>
using namespace std;

// Function to calculate the Fibonacci series using recursion
int fibonacciRecursion(int n) {
    if (n <= 1)
        return n;
    return fibonacciRecursion(n - 1) + fibonacciRecursion(n - 2);
}

// Function to calculate the Fibonacci series using memoization
int fibonacciMemoization(int n, vector<int>& memo) {
    if (n <= 1)
        return n;
    if (memo[n] != -1)
        return memo[n];
    memo[n] = fibonacciMemoization(n - 1, memo) + fibonacciMemoization(n - 2, memo);
    return memo[n];
}

// Function to calculate the Fibonacci series using dynamic programming
int fibonacciDynamicProgramming(int n) {
    if (n <= 1)
        return n;
    int a = 0, b = 1, c;
    for (int i = 2; i <= n; i++) {
        c = a + b;
        a = b;
        b = c;
    }
    return b;
}

