import java.util.ArrayList;
import java.util.List;

public class FibonacciSequence {

    public static void main(String[] args) {
        int x = 3;
        int y = 4;
        int n = 6;

        List<Integer> sequence = generateModifiedFibonacci(x, y, n);

        System.out.println(sequence);

        int nthNumber = findNthModifiedFibonacci(x, y, n);

        System.out.println("The " + n + "th number in the sequence is " + nthNumber);
    }

    public static List<Integer> generateModifiedFibonacci(int x, int y, int n) {
        List<Integer> sequence = new ArrayList<>();
        sequence.add(x);
        sequence.add(y);

        for (int i = 2; i < n; i++) {
            int nextNumber = sequence.get(i-1) + sequence.get(i-2);
            sequence.add(nextNumber);
        }

        return sequence;
    }

    public static int findNthModifiedFibonacci(int x, int y, int n) {
        if (n == 1) {
            return x;
        } else if (n == 2) {
            return y;
        } else {
            return findNthModifiedFibonacci(x, y, n-1) + findNthModifiedFibonacci(x, y, n-2);
        }
    }
}
