    }

    // Compute LCS length using the recursive helper function
    int lcs = lcs_recursive(X, Y, m, n, memo);

    // Free memory
    for (int i = 0; i <= m; i++) {
        free(memo[i]);
    }
    free(memo);

    return lcs;
}

int lcs_recursive(const char* X, const char* Y, int m, int n, int** memo) {
    // Base case: if either of the strings is empty, LCS length is 0
    if (m == 0 || n == 0) {
        return 0;
    }

    // If the subproblem has already been solved, return the stored result
    if (memo[m][n] != -1) {
        return memo[m][n];
    }

    // If the last characters of both strings match, recursively compute LCS
    // length for the remaining substrings and add 1 to the result
    if (X[m - 1] == Y[n - 1]) {
        memo[m][n] = 1 + lcs_recursive(X, Y, m - 1, n - 1, memo);
    } else {
        // If the last characters don't match, recursively compute LCS length
        // for the remaining substrings by considering both possibilities
        int lcs1 = lcs_recursive(X, Y, m - 1, n, memo);
        int lcs2 = lcs_recursive(X, Y, m, n - 1, memo);
        memo[m][n] = (lcs1 > lcs2) ? lcs1 : lcs2;
    }

    return memo[m][n];
}

int main() {
    const char* X = "AGGTAB";
    const char* Y = "GXTXAYB";

    int lcs = lcs_length(X, Y);
    printf("Length of Longest Common Subsequence: %d\n", lcs);

    return 0;
}
```

The `lcs_length` function takes two strings `X` and `Y` as input and returns the length of their Longest Common Subsequence. It first allocates memory for a memoization table (`memo`) to store the computed results of subproblems. Then, it calls the recursive helper function `lcs_recursive` to compute the LCS length using memoization. Finally, it frees the allocated memory and returns the LCS length.

The `lcs_recursive` function is a helper function that computes the LCS length recursively. It takes two strings `X` and `Y`, the lengths of their respective substrings (`m` and `n`), and the memoization table (`memo`) as input. It first checks the base case when either of the substrings is empty, in which case it returns 0. If the result of the current subproblem is already stored in the memoization table, it directly returns the stored result. Otherwise, it checks if the last characters of both strings match. If they do, it recursively computes the LCS length for the remaining substrings and adds 1 to the result. If they don't match, it recursively computes the LCS length for the remaining substrings by considering both possibilities (excluding the last character from `X` or `Y`). It stores the computed result in the memoization table and returns it.

In the `main` function, an example usage of the LCS algorithm is demonstrated by finding the length of the LCS between the strings "AGGTAB" and "GXTXAYB". The result is then printed on the console.

