            return BigInteger.ONE;

        // Calculate fibonacci(n) using matrix exponentiation
        BigInteger[][] matrix = {{BigInteger.ONE, BigInteger.ONE},
                {BigInteger.ONE, BigInteger.ZERO}};
        if (n.compareTo(BigInteger.ZERO) < 0) {
            matrix = new BigInteger[][]{{BigInteger.ZERO, BigInteger.ONE},
                    {BigInteger.ONE, BigInteger.ONE}};
            n = n.negate();
        }
        matrix = matrixPower(matrix, n.subtract(BigInteger.ONE));

        // Return the fibonacci(n) modulo p
        return matrix[0][0].mod(p);
    }

    private static BigInteger[][] matrixPower(BigInteger[][] matrix, BigInteger exponent) {
        if (exponent.equals(BigInteger.ZERO))
            return new BigInteger[][]{{BigInteger.ONE, BigInteger.ZERO},
                    {BigInteger.ZERO, BigInteger.ONE}};
        if (exponent.mod(BigInteger.TWO).equals(BigInteger.ZERO)) {
            BigInteger[][] half = matrixPower(matrix, exponent.divide(BigInteger.TWO));
            return matrixMultiply(half, half);
        } else {
            BigInteger[][] half = matrixPower(matrix, exponent.subtract(BigInteger.ONE).divide(BigInteger.TWO));
            return matrixMultiply(matrixMultiply(half, half), matrix);
        }
    }

    private static BigInteger[][] matrixMultiply(BigInteger[][] a, BigInteger[][] b) {
        BigInteger[][] result = new BigInteger[2][2];
        result[0][0] = a[0][0].multiply(b[0][0]).add(a[0][1].multiply(b[1][0]));
        result[0][1] = a[0][0].multiply(b[0][1]).add(a[0][1].multiply(b[1][1]));
        result[1][0] = a[1][0].multiply(b[0][0]).add(a[1][1].multiply(b[1][0]));
        result[1][1] = a[1][0].multiply(b[0][1]).add(a[1][1].multiply(b[1][1]));
        return result;
    }

    public static void main(String[] args) {
        BigInteger n = new BigInteger("1000000000");
        BigInteger p = new BigInteger("1000000007");
        BigInteger fibonacci = fibonacci(n, p);
        System.out.println(fibonacci);
    }
}
```

